async function translate(text, attempt = 1) {
  const sys =
    attempt === 1
      ? "你是技术文档翻译器。将输入全部翻译成简体中文。保留 Markdown、英文标识符、路径、文件名、代码、UUID、session id。只输出译文，不要问候。"
      : "必须输出完整简体中文译文。禁止留葡语。禁止空回复。保留 Markdown 结构与代码不变。";
  const res = await fetch("http://127.0.0.1:3425/v1/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "auto/hy3",
      temperature: 0,
      max_tokens: 8192,
      messages: [
        { role: "system", content: sys },
        { role: "user", content: text },
      ],
    }),
  });
  if (!res.ok) throw new Error(`VLM ${res.status}`);
  const j = await res.json();
  const out = (j.choices?.[0]?.message?.content || "").trim();
  if (!out || REFUSE.test(out)) {
    if (attempt < 3) return translate(text, attempt + 1);
    throw new Error("bad translation: " + out.slice(0, 80));
  }
  if (PT_STRONG.test(out)) {
    if (attempt < 3) return translate(text + "\n\n(再次强调：全部译为简体中文)", attempt + 1);
    throw new Error("still PT in output");
  }
  return out;
}

