const PT_LINE =
  /^\s*[-*].*\b(Antes de|Alterar|Centralizar|Sessão de|Tratar|Alterado|Deve|Não|Para o|com o|no diretório|dos quais|concluí|substitu|migra|validação|formulário|botão|diálogo|colunas de|gestão de|Formato do|Menu de|Barra de|Exibição de|Padronização|Aviso de|Cálculo de|Código de|Componente de|Coluna de|encapsulamento|sobrescrita|margem inferior|chave v for)\b/im;
