function split(raw) {
  const m = raw.match(/^(.*)(<!-- MEMORY_FIELDS[\s\S]*?-->\s*)$/s);
  if (!m) return { body: raw.trimEnd(), fields: null, block: "" };
  return { body: m[1].trimEnd(), fields: m[2], block: m[2] };
}

function needsWork(rel, body, raw) {
  if (PT_ACCENT.test(rel) || PT_ACCENT.test(body)) return true;
